Order conditions (minimum amount, participating lines) are checked by
:func:`shop.pricing.calculate_total`; the registry only knows about existence,
validity period and the usage limit.
"""

from __future__ import annotations

import logging
import threading
from collections.abc import Iterable
from dataclasses import dataclass, field
from datetime import datetime
from decimal import Decimal
from enum import StrEnum

from .catalog import Category, normalize_key
from .clock import Clock, SystemClock
from .errors import (
    PromoConditionsError,
    PromoExpiredError,
    UnknownPromoCodeError,
    ValidationError,
)
from .money import ZERO, to_money

logger = logging.getLogger(__name__)

HUNDRED = Decimal("100")


class DiscountKind(StrEnum):
    PERCENT = "percent"
    FIXED = "fixed"


def _require_decimal(value: object, what: str) -> Decimal:
    if isinstance(value, bool) or not isinstance(value, (Decimal, int)):
        raise ValidationError(f"{what} must be Decimal or int")
