            promo = self._resolve_locked(code, customer_id)
            self._uses[promo.code] += 1
            if customer_id is not None:
                by_customer = self._uses_by_customer[promo.code]
                by_customer[customer_id] = by_customer.get(customer_id, 0) + 1
            return promo

