        """Give back one use (never below zero); the validity period is not checked."""
        customer_id = require_customer_id(customer_id)
        key = normalize_key(code)
        with self._lock:
            if key not in self._codes:
                logger.warning("promo: release of unknown code %r ignored", key)
                return
            self._uses[key] = max(0, self._uses[key] - 1)
            if customer_id is not None:
                by_customer = self._uses_by_customer[key]
                by_customer[customer_id] = max(0, by_customer.get(customer_id, 0) - 1)

    def _lookup(self, code: str) -> PromoCode:
        key = normalize_key(code)
        try:
            return self._codes[key]
        except KeyError:
            raise UnknownPromoCodeError(f"unknown promo code: {key!r}") from None

    def _resolve_locked(self, code: str, customer_id: str | None) -> PromoCode:
        promo = self._lookup(code)
        if not promo.is_active_at(self._clock.now()):
            raise PromoExpiredError(f"promo code {promo.code} is not active")
        if promo.max_uses is not None and self._uses[promo.code] >= promo.max_uses:
